#!/usr/bin/env python3
"""svc - service-control CLI for the metricsaggd (and friends) platform.

Reads service definitions from /home/user/etc/services.conf and exposes
LSB-style subcommands:

    start, stop, restart, status, enable, disable, is-active,
    is-enabled, list

Exit codes:
    0 - success / active / enabled
    1 - generic failure / not enabled
    3 - inactive
"""
from __future__ import annotations

import configparser
import json
import os
import subprocess
import sys
import time
from pathlib import Path

SERVICES_CONF = Path("/home/user/etc/services.conf")
ENABLED_FILE = Path("/home/user/var/enabled.json")
DEFAULT_SERVICE = "metricsaggd"


def load_services_conf(path: Path = SERVICES_CONF) -> dict:
    cp = configparser.ConfigParser()
    if path.exists():
        cp.read(path)
    return {section: dict(cp.items(section)) for section in cp.sections()}


def read_enabled(path: Path = ENABLED_FILE) -> list:
    if not path.exists():
        return []
    try:
        data = json.loads(path.read_text() or "[]")
    except json.JSONDecodeError:
        data = []
    if not isinstance(data, list):
        data = []
    return [str(x) for x in data]


def write_enabled(items, path: Path = ENABLED_FILE) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(sorted(set(items))))


def is_process_alive(pid: int) -> bool:
    if pid <= 0:
        return False
    try:
        os.kill(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True


def is_active(svc: dict) -> bool:
    """A service is active iff its pid_file exists AND its PID is alive.

    The pid_file's existence is the authoritative signal — once the
    daemon removes its PID file on shutdown, the kernel is free to
    recycle that PID to an unrelated process.
    """
    pid_file = svc.get("pid_file", "")
    if not pid_file or not os.path.exists(pid_file):
        return False
    try:
        pid = int(Path(pid_file).read_text().strip())
    except (ValueError, OSError):
        return False
    return is_process_alive(pid)


def read_pid(svc: dict):
    pid_file = svc.get("pid_file", "")
    if not pid_file or not os.path.exists(pid_file):
        return None
    try:
        return int(Path(pid_file).read_text().strip())
    except (ValueError, OSError):
        return None


def wait_for_pid_file(pid_file: str, timeout: float = 3.0) -> int:
    deadline = time.time() + timeout
    pf = Path(pid_file)
    while time.time() < deadline:
        if pf.exists():
            try:
                pid = int(pf.read_text().strip())
                if is_process_alive(pid):
                    return pid
            except (ValueError, OSError):
                pass
        time.sleep(0.05)
    raise TimeoutError(f"PID file {pid_file} did not appear within {timeout}s")


def wait_for_shutdown(pid_file: str, pid: int, timeout: float = 5.0) -> bool:
    """Wait for the daemon to shut down.

    Watches both the PID file's disappearance AND the original PID's
    liveness. PID file is the authoritative signal because the PID
    can be recycled by the kernel.
    """
    pf = Path(pid_file)
    deadline = time.time() + timeout
    while time.time() < deadline:
        if not pf.exists():
            return True
        if not is_process_alive(pid):
            end = time.time() + 0.2
            while time.time() < end and pf.exists():
                time.sleep(0.05)
            if not pf.exists():
                return True
            return True
        time.sleep(0.05)
    return not pf.exists()


def cmd_start(svc_name: str, services: dict) -> int:
    if svc_name not in services:
        sys.stderr.write(f"Unknown service: {svc_name}\n")
        return 1
    svc = services[svc_name]
    if is_active(svc):
        pid = read_pid(svc)
        print(f"{svc_name} started (pid {pid})")
        return 0
    executable = svc.get("executable", "")
    config = svc.get("config", "")
    if not executable:
        sys.stderr.write(f"Service {svc_name} has no executable defined\n")
        return 1
    cmd = [sys.executable, executable]
    if config:
        cmd.extend(["--config", config])
    try:
        subprocess.Popen(
            cmd,
            stdout=subprocess.DEVNULL,
            stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
        pid = wait_for_pid_file(svc["pid_file"], timeout=3.0)
    except (FileNotFoundError, TimeoutError, OSError) as exc:
        sys.stderr.write(f"Failed to start {svc_name}: {exc}\n")
        return 1
    print(f"{svc_name} started (pid {pid})")
    return 0


def cmd_stop(svc_name: str, services: dict) -> int:
    if svc_name not in services:
        sys.stderr.write(f"Unknown service: {svc_name}\n")
        return 1
    svc = services[svc_name]
    pid = read_pid(svc)
    pid_file = svc.get("pid_file", "")
    if pid is None or not is_process_alive(pid):
        if pid_file and os.path.exists(pid_file):
            try:
                os.unlink(pid_file)
            except OSError:
                pass
        print(f"{svc_name} stopped")
        return 0
    try:
        os.kill(pid, 15)
    except ProcessLookupError:
        print(f"{svc_name} stopped")
        return 0
    except PermissionError as exc:
        sys.stderr.write(f"Failed to stop {svc_name}: {exc}\n")
        return 1
    if not wait_for_shutdown(pid_file, pid, timeout=5.0):
        sys.stderr.write(f"Service {svc_name} did not exit within timeout\n")
        return 1
    print(f"{svc_name} stopped")
    return 0


def cmd_restart(svc_name: str, services: dict) -> int:
    rc = cmd_stop(svc_name, services)
    if rc != 0:
        return rc
    return cmd_start(svc_name, services)


def cmd_status(svc_name: str, services: dict) -> int:
    if svc_name not in services:
        sys.stderr.write(f"Unknown service: {svc_name}\n")
        return 3
    svc = services[svc_name]
    if is_active(svc):
        pid = read_pid(svc)
        print(f"active (pid {pid})")
        return 0
    print("inactive (dead)")
    return 3


def cmd_is_active(svc_name: str, services: dict) -> int:
    if svc_name not in services:
        return 3
    return 0 if is_active(services[svc_name]) else 3


def cmd_enable(svc_name: str, _services: dict) -> int:
    items = read_enabled()
    if svc_name not in items:
        items.append(svc_name)
    write_enabled(items)
    print(f"{svc_name} enabled")
    return 0


def cmd_disable(svc_name: str, _services: dict) -> int:
    items = [x for x in read_enabled() if x != svc_name]
    write_enabled(items)
    print(f"{svc_name} disabled")
    return 0


def cmd_is_enabled(svc_name: str, _services: dict) -> int:
    return 0 if svc_name in read_enabled() else 1


def cmd_list(services: dict) -> int:
    enabled = sorted(set(read_enabled()))
    for name in enabled:
        svc = services.get(name, {})
        marker = "active" if is_active(svc) else "inactive"
        print(f"{name}\t{marker}")
    return 0


DISPATCH = {
    "start": cmd_start,
    "stop": cmd_stop,
    "restart": cmd_restart,
    "status": cmd_status,
    "enable": cmd_enable,
    "disable": cmd_disable,
    "is-active": cmd_is_active,
    "is-enabled": cmd_is_enabled,
}


def usage() -> None:
    sys.stderr.write(
        "Usage: svc.py <subcommand> [service]\n"
        f"Subcommands: {', '.join(DISPATCH)}\n"
    )


def main(argv=None) -> int:
    args = list(argv if argv is not None else sys.argv[1:])
    if not args:
        usage()
        return 1
    subcmd = args[0]
    services = load_services_conf()
    if subcmd == "list":
        return cmd_list(services)
    svc_name = args[1] if len(args) > 1 else DEFAULT_SERVICE
    handler = DISPATCH.get(subcmd)
    if handler is None:
        usage()
        return 1
    return handler(svc_name, services)


if __name__ == "__main__":
    sys.exit(main())
